const events = readEventsFor('Setup guide', example.parameters.windowMinutes);
const refusals = events.filter(event => event.kind === 'Edit blocked');

const gateRows = [];
for (const [runId, edits] of Map.groupBy(refusals, edit => edit.gateRunId)) {
  gateRows.push({ ...readGateRow(runId, 'Guide links'), refusals: edits });
}

const orders = [];
for (const [orderId, rows] of Map.groupBy(gateRows, row => row.orderId)) {
  orders.push({ ...readWorkOrder(orderId), evidence: rows });
}

const planningPasses = [];
for (const [passId, assignments] of Map.groupBy(orders, order => order.passId)) {
  planningPasses.push({ ...readPlanningPass(passId), assignments });
}

